// Prüfen ob alles da ist
if (!data.location || !data.nextStopLocation || !data.nextStopArrival) {
    node.error("Fehlende notwendige Felder", msg);
    return null;
}

// Zeit sauber erzeugen
let now = new Date();
let arrival = new Date(data.nextStopArrival);

// Zeitdifferenz in Sekunden
let timeDiff = (arrival.getTime() - now.getTime()) / 1000;

// Koordinaten
let latStart = data.location.coordinates[0];
let lonStart = data.location.coordinates[1];

let latEnd = data.nextStopLocation.coordinates[0];
let lonEnd = data.nextStopLocation.coordinates[1];

msg.payload.data[0].timeDiff = timeDiff;
msg.payload.data[0].latStart = latStart;
msg.payload.data[0].lonStart = lonStart;
msg.payload.data[0].latEnd = latEnd;
msg.payload.data[0].lonEnd = lonEnd;


// Wenn Zeit abgelaufen → Ziel
if (timeDiff <= 0) {

    msg.payload.data[0].locationUpdate = {
        "type":"GeoProperty",
        "value":{"type":"Point",
            "coordinates":[latEnd,lonEnd]}
    }
    msg.payload.data[0].stateADStack = "StopReached";

    if (msg.payload.data[0].state === "Approaching") {
        msg.payload.data[0].state = "Boarding";
    } else if (msg.payload.data[0].state === "Riding") {
        msg.payload.data[0].state = "OffBoarding";
    }

    return msg;
}

// Differenzen
let deltaLat = latEnd - latStart;
let deltaLon = lonEnd - lonStart;

msg.payload.data[0].deltaLat = deltaLat;
msg.payload.data[0].deltaLon = deltaLon;


// Faktor
let factor = interval / timeDiff;
if (factor >= 1) {
        factor = 1;
        msg.payload.data[0].stateADStack = "StopReached";

        if (msg.payload.data[0].state === "Approaching") {
            msg.payload.data[0].state = "Boarding";
        } else if (msg.payload.data[0].state === "RidingToKonvoi") {
            msg.payload.data[0].state = "RidingInKonvoi";
        } else if (msg.payload.data[0].state === "RidingInKonvoi") {
            msg.payload.data[0].state = "Riding";
        } else if (msg.payload.data[0].state === "Riding") {
            msg.payload.data[0].state = "OffBoarding";
        }
    }

// Neue Position
let latNew = latStart + deltaLat * factor;
let lonNew = lonStart + deltaLon * factor;

// Ergebnis
msg.payload.data[0].locationUpdate = {
    "type":"GeoProperty",
    "value":{"type":"Point",
        "coordinates":[latNew,lonNew]}
}

return msg;

