}

if (data.stateADStack  !== undefined && data.stateADStack === "StopReached") {
    ngsiEntity.stateADStack = {
        "type": "Property",
        "value": data.stateADStack
    };

    warnMessage = warnMessage + " - stateADStack: " + ngsiEntity.stateADStack.value;

}


if (data.state !== undefined) {

    ngsiEntity.state = {
        "type": "Property",
        "value": data.state
    };

    if (data.state == "Approaching" || data.state == "Riding") {

    warnMessage = warnMessage + (" -  Cab Status: " + ngsiEntity.state.value);

    } else if (data.state == "Boarding") {

    warnMessage = warnMessage + (" -  Neuer Cab Status: " + ngsiEntity.state.value);

    } else if (data.state == "OffBoarding") {

    warnMessage = warnMessage + (" -  Neuer Cab Status: " + ngsiEntity.state.value);

    }
}

// node.warn(warnMessage);

msg.payload = ngsiEntity;

