    "type": "Vehicle",
    "@context": ["https://api.npoint.io/d66beea7313de1ad894c"]
};

// Conditionally add each attribute if present
if (input.position_latitude !== undefined && input.position_longitude !== undefined) {
    ngsiEntity.location = {
        "type": "GeoProperty",
        "value": {
            "type": "Point",
            "coordinates": [input.position_longitude, input.position_latitude]
        }
    };
}

if (input.position_heading !== undefined) {
    ngsiEntity.bearing = {
        "type": "Property",
        "value": input.position_heading
    };
}

if (input.velocity !== undefined) {
    ngsiEntity.speed = {
        "type": "Property",
        "value": input.velocity
    };
}

if (input.state_of_charge !== undefined) {
    ngsiEntity.batteryLevel = {
        "type": "Property",
        "value": input.state_of_charge
    };
}

if (input.ad_status !== undefined) {
    ngsiEntity.stateADStack = {
        "type": "Property",
        "value": "Idle"
        //"value": input.ad_status
    };
}

if (input.ad_nemo_status !== undefined) {
    ngsiEntity.state = {
        "type": "Property",
        "value": "Idle"
        //"value": input.ad_nemo_status
    };
}
msg.payload = ngsiEntity;

return msg;

msg.headers = {
    "Content-Type": "application/ld+json",
    "Accept": "application/ld+json",
    "NGSILD-Tenant": "default_dataspace"
};

msg.method = 'PATCH';
msg.url = env.get("NGSI_LD_SERVER") + "/ngsi-ld/v1/entities/" + flow.get("id") + "/attrs"

// node.warn(msg.url)

return msg;
